def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """Return True if any two numbers in the list are closer than ``threshold``."""
    if len(numbers) < 2:
        return False
    # Sort the numbers to only compare adjacent pairs
    sorted_nums = sorted(numbers)
    for a, b in zip(sorted_nums, sorted_nums[1:]):
        if abs(b - a) < threshold:
            return True
    return False

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def mean_absolute_deviation(numbers: List[float]) -> float:
    """Calculate the mean absolute deviation of a list of numbers."""
    if not numbers:
        return 0.0
    mean_val = sum(numbers) / len(numbers)
    return sum(abs(x - mean_val) for x in numbers) / len(numbers)

def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    for idx in range(n - 1, -1, -1):
        a, b, g, k = carpets[idx]
        if a <= x <= a + g and b <= y <= b + k:
            return idx + 1
    return -1

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Build grid with 0-indexing
    grid = [[0] * N for _ in range(N)]
    for x, y, v in grid_values:
        if x == 0 and y == 0 and v == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x - 1][y - 1] = v

    # Edge case: single cell
    if N == 1:
        return grid[0][0]

    # DP: dp[x1][x2] current maximum sum for step k
    INF_NEG = -10**9
    dp = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
    # k = 2 -> both at (1,1)
    dp[1][1] = grid[0][0]

    # Steps from 3 to 2N
    for k in range(3, 2 * N + 1):
        dp_next = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
        # x1 ranges such that y1 = k - x1 is valid
        x1_min = max(1, k - N)
        x1_max = min(N, k - 1)
        for x1 in range(x1_min, x1_max + 1):
            y1 = k - x1
            if y1 < 1 or y1 > N:
                continue
            for x2 in range(x1_min, x1_max + 1):
                y2 = k - x2
                if y2 < 1 or y2 > N:
                    continue
                best = INF_NEG
                # Four combinations of previous moves
                for dx1 in (0, 1):  # 0: came from left (x same), 1: came from up (x-1)
                    for dx2 in (0, 1):
                        prev_x1 = x1 - dx1
                        prev_x2 = x2 - dx2
                        if prev_x1 < 1 or prev_x2 < 1:
                            continue
                        val = dp[prev_x1][prev_x2]
                        if val > best:
                            best = val
                if best == INF_NEG:
                    continue
                added = grid[x1 - 1][y1 - 1]
                if x1 != x2:
                    added += grid[x2 - 1][y2 - 1]
                dp_next[x1][x2] = best + added
        dp = dp_next

    return dp[N][N] if dp[N][N] > INF_NEG else 0

def cantor_numbering(N: int) -> str:
    """Return the N-th fraction in Cantor's table."""
    lo, hi = 1, N
    while lo < hi:
        mid = (lo + hi) // 2
        if mid * (mid + 1) // 2 >= N:
            hi = mid
        else:
            lo = mid + 1
    d = lo
    prev_cum = (d - 1) * d // 2
    offset = N - prev_cum - 1
    if d % 2 == 0:
        numerator = 1 + offset
        denominator = d - offset
    else:
        numerator = d - offset
        denominator = 1 + offset
    return f"{numerator}/{denominator}"

def process_random_numbers(numbers: List[int]) -> Tuple[int, List[int]]:
    unique_numbers = sorted(set(numbers))
    return len(unique_numbers), unique_numbers

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    tokens = []
    for i, coef in enumerate(coeffs):
        if coef == 0:
            continue
        degree = n - i
        # sign
        if not tokens:
            sign = '-' if coef < 0 else ''
        else:
            sign = '-' if coef < 0 else '+'
        abs_coef = abs(coef)
        # coefficient part
        if abs_coef == 1 and degree != 0:
            coef_part = ''
        else:
            coef_part = str(abs_coef)
        # variable part
        if degree == 0:
            var_part = ''
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = f'x^{degree}'
        tokens.append(f'{sign}{coef_part}{var_part}')
    return ''.join(tokens) if tokens else '0'

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"
    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o
    # Ensure mapping is a full bijection over the alphabet
    if len(mapping) < 26:
        return "Failed"
    # Now decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])
    return "".join(decoded_chars)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Returns the minimum number of steps if possible within 10 steps, otherwise
    "NO ANSWER!".
    """
    if A == B:
        return 0

    from collections import deque

    # BFS initialization
    queue = deque([(A, 0)])
    visited = {A}

    while queue:
        current, step = queue.popleft()
        if step >= 10:
            continue  # do not explore beyond 10 steps

        # Try all rules on all positions
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                # Generate new string
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return step + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, step + 1))
                # Move start to next position (allow overlapping patterns)
                start = idx + 1

    return "NO ANSWER!"

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers by applying digit transformation rules.

    Each rule (x, y) allows a single digit `x` to be transformed into digit `y`.
    We explore all possible transformations using breadth‑first search (BFS).
    The function returns the total count of unique numbers that can be generated
    from the original number `n`, including `n` itself.

    :param n: The original integer number to transform.
    :param rules: List of tuples (x, y) indicating digit transformation rules.
    :return: Count of unique numbers reachable via the rules.
    """
    # Convert starting number to its string representation
    start_str = str(n)

    # Mapping from source digit to list of destination digits (as strings)
    rule_map = {}
    for src, dst in rules:
        key = str(src)
        val = str(dst)
        rule_map.setdefault(key, []).append(val)

    # BFS initialization
    visited = {start_str}
    queue = [start_str]

    while queue:
        current = queue.pop(0)
        # For each digit position, try to apply applicable rules
        for idx, digit in enumerate(current):
            if digit in rule_map:
                for target_digit in rule_map[digit]:
                    new_number = current[:idx] + target_digit + current[idx + 1:]
                    if new_number not in visited:
                        visited.add(new_number)
                        queue.append(new_number)

    return len(visited)

def calculate_arrangements(n, m, a) -> int:
    mod = 10**6 + 7
    # Edge case: if total capacity less than m, no arrangements
    if sum(a) < m:
        return 0
    dp = [0] * (m + 1)
    dp[0] = 1
    for max_k in a:
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for i in range(1, m + 1):
            prefix[i] = (prefix[i-1] + dp[i]) % mod
        new_dp = [0] * (m + 1)
        for k in range(m + 1):
            left = k - max_k
            if left <= 0:
                new_dp[k] = prefix[k]
            else:
                new_dp[k] = (prefix[k] - prefix[left - 1]) % mod
        dp = new_dp
    return dp[m] % mod

def sort_students(student_scores):
    """Sort students by total score descending, then Chinese score descending, then student number ascending."""
    return sorted(student_scores, key=lambda s: (-s[1], -s[2], s[0]))

def hanoi_double_iterative(n: int) -> int:
    """Calculate the minimum number of moves required to solve the double-disc Hanoi Towers problem for n pairs of discs."""
    if n <= 0:
        return 0
    # Known closed form: 2^(n+1) - 2
    return (1 << (n + 1)) - 2
